import itertools

def simulate(n, permutation):
    # Each element is [person_id, tag_id]
    # person_id is the original index (0 to n-1)
    # tag_id is the tag they currently hold
    guests = [[i, permutation[i]] for i in range(n)]

    for _ in range(4):
        # i) Any guest who has their own name tag exits the table
        remaining_guests = []
        for g in guests:
            if g[0] != g[1]:
                remaining_guests.append(g)

        if not remaining_guests:
            return False

        guests = remaining_guests

        # ii) The remaining guests pass their name tags to the guest sitting immediately to their right.
        # If guests are in a circle: g0, g1, ..., gk-1
        # g0 passes tag to g1, g1 to g2, ..., gk-1 to g0.
        # So new tag of g_i is the tag of g_{i-1}
        new_guests = []
        num_remaining = len(guests)
        for i in range(num_remaining):
            # The tag guest i gets is the tag guest i-1 had
            new_tag = guests[(i - 1) % num_remaining][1]
            new_guests.append([guests[i][0], new_tag])

        guests = new_guests

    return len(guests) > 0

def count_valid_permutations(n):
    count = 0
    for p in itertools.permutations(range(n)):
        if simulate(n, p):
            count += 1
    return count

