def permanent_circulant_small(N, k):
    # M[i, j] = 1 if (j-i)%N < k else 0
    # We want to compute the permanent of M.
    # We use DP with bitmask.
    # Because it's circulant, we can fix the first row's choice to handle wrap-around.
    # However, it's easier to just use a bitmask of all N columns.
    # For N=16, 2^16 = 65536. 16 * 65536 = 1,048,576.
    # This is small enough to compute directly!

    dp = [0] * (1 << N)
    dp[0] = 1
    for i in range(N):
        new_dp = [0] * (1 << N)
        allowed_cols = [(i + j) % N for j in range(k)]
        for mask in range(1 << N):
            if dp[mask] == 0:
                continue
            for col in allowed_cols:
                if not (mask & (1 << col)):
                    new_dp[mask | (1 << col)] += dp[mask]
        dp = new_dp
    return dp[(1 << N) - 1]

