from scipy.special import factorial

def permanent(matrix):
    # Ryser's formula for permanent
    n = len(matrix)
    perm = 0
    for i in range(1 << n):
        subset_sum = np.zeros(n)
        count = 0
        for j in range(n):
            if (i >> j) & 1:
                subset_sum += matrix[:, j]
                count += 1

        prod = np.prod(subset_sum)
        if (n - count) % 2 == 1:
            perm -= prod
        else:
            perm += prod
    return int(perm)

def solve_gn(n, r):
    matrix = np.zeros((n, n), dtype=int)
    for i in range(n):
        for j in range(n):
            if (j - i) % n < r:
                matrix[i, j] = 1

    total_perms = factorial(n)
    perm_m = permanent(matrix)
    return total_perms - perm_m

