    for i in range(n):
        current_state.append((i + 1, initial_tags[i]))

    for round_num in range(1, 5):
        next_state = []
        for g_id, t_id in current_state:
            if g_id != t_id:
                next_state.append((g_id, t_id))

        if not next_state:
            return False

        current_state = next_state
        m = len(current_state)
        new_tags = [None] * m
        for k in range(m):
            new_tags[k] = current_state[(k - 1) % m][1]

        current_state = [(current_state[k][0], new_tags[k]) for k in range(m)]

    return len(current_state) > 0

def count_stays(n):
    count = 0
    for p in itertools.permutations(range(1, n + 1)):
        if simulate(n, p):
            count += 1
    return count

for n in range(1, 11):
    print(f"N={n}: {count_stays(n)}")

import itertools

def solve_small(n):
    count = 0
    for sigma in itertools.permutations(range(n)):
        guests = list(range(n))
        tags = list(sigma)
        remains = True
        for _ in range(4):
            exited_indices = []
            for i in range(len(guests)):
                if tags[i] == guests[i]:
                    exited_indices.append(i)

            if not exited_indices:
                new_tags = [None] * len(tags)
                for i in range(len(tags)):
                    new_tags[(i + 1) % len(tags)] = tags[i]
                tags = new_tags
            else:
                for i in sorted(exited_indices, reverse=True):
                    guests.pop(i)
                    tags.pop(i)
                new_tags = [None] * len(tags)
                for i in range(len(tags)):
                    new_tags[(i + 1) % len(tags)] = tags[i]
                tags = new_tags

            if len(guests) == 0:
                remains = False
                break
        if remains and len(guests) > 0:
            count += 1
    return count

