import time

def simulate_correct(n, sigma):
    current_tags = list(sigma)
    occupied_positions = list(range(n))
    for round_num in range(1, 5):
        new_occupied_positions = []
        for p in occupied_positions:
            if current_tags[p] != p:
                new_occupied_positions.append(p)
        if not new_occupied_positions:
            return False
        occupied_positions = new_occupied_positions
        m = len(occupied_positions)
        new_tags = [None] * n
        for j in range(m):
            curr_p = occupied_positions[j]
            next_p = occupied_positions[(j + 1) % m]
            new_tags[next_p] = current_tags[curr_p]
        current_tags = new_tags
    return True

def get_G(n):
    count = 0
    for p in itertools.permutations(range(n)):
        if simulate_correct(n, p):
            count += 1
    return count

