def solve():
    n = 16
    # dp[i][mask][k]
    # To save memory, we can use only two layers for i.
    # mask is 16 bits.
    dp = [[0] * (n + 1) for _ in range(1 << n)]
    dp[0][0] = 1

    for i in range(n):
        new_dp = [[0] * (n + 1) for _ in range(1 << n)]
        for mask in range(1 << n):
            for k in range(i + 1):
                if dp[mask][k] == 0:
                    continue

                # Option 1: Don't pick any column for row i
                new_dp[mask][k] += dp[mask][k]

                # Option 2: Pick one of the 4 columns
                for j in range(4):
                    col = (i + j) % n
                    if not (mask & (1 << col)):
                        new_dp[mask | (1 << col)][k + 1] += dp[mask][k]
        dp = new_dp

    r = [0] * (n + 1)
    for mask in range(1 << n):
        for k in range(n + 1):
            r[k] += dp[mask][k]

    import math
    ans = 0
    for k in range(n + 1):
        term = r[k] * math.factorial(n - k)
        if k % 2 == 1:
            ans -= term
        else:
            ans += term
    return ans

