import itertools

def simulate_game(n, sigma):
    guests = list(range(n))
    tags = list(sigma)
    for r in range(4):
        exited_indices = []
        for i in range(len(guests)):
            if tags[i] == guests[i]:
                exited_indices.append(i)

        if not exited_indices:
            # Pass
            new_tags = [None] * len(tags)
            for i in range(len(tags)):
                new_tags[(i + 1) % len(tags)] = tags[i]
            tags = new_tags
        else:
            # Exit and Pass
            for i in sorted(exited_indices, reverse=True):
                guests.pop(i)
                tags.pop(i)
            new_tags = [None] * len(tags)
            for i in range(len(tags)):
                new_tags[(i + 1) % len(tags)] = tags[i]
            tags = new_tags

        if len(guests) == 0:
            return False # Everyone left
    return len(guests) > 0 # Someone stays

def count_stays(n):
    count = 0
    for sigma in itertools.permutations(range(n)):
        if simulate_game(n, sigma):
            count += 1
    return count

